  expect(older).toMatchObject({ ok: false, error: { code: 'SCHEMA_VERSION_CONFLICT' } });
  expect(newer.ok).toBe(true);
  expect(await schemaGet({ db }, { dataset: 'prod' })).toMatchObject({ ok: true, result: { version: 3 } });
});

