/**
 * Network activity collector - tracks HTTP requests
 */

import type { NetworkRequest, ContextCollector } from "../core/types.js";

export class NetworkCollector implements ContextCollector<NetworkRequest[]> {
  private requests: NetworkRequest[] = [];
  private maxSize: number;
  private originalFetch?: typeof fetch;
  private originalXHROpen?: typeof XMLHttpRequest.prototype.open;
  private originalXHRSend?: typeof XMLHttpRequest.prototype.send;
  private isActive = false;
  private sensitiveHeaders = new Set([
    "authorization",
    "cookie",
    "set-cookie",
    "x-api-key",
    "x-auth-token",
  ]);

  constructor(maxSize: number = 20) {
    this.maxSize = maxSize;
  }

  /**
   * Start intercepting network requests
   */
  start(): void {
    if (this.isActive) return;

    this.interceptFetch();
    this.interceptXHR();

    this.isActive = true;
  }

  /**
   * Stop intercepting network requests
   */
  stop(): void {
    if (!this.isActive) return;

    if (this.originalFetch) {
      globalThis.fetch = this.originalFetch;
    }

    if (this.originalXHROpen) {
      XMLHttpRequest.prototype.open = this.originalXHROpen;
    }

    if (this.originalXHRSend) {
      XMLHttpRequest.prototype.send = this.originalXHRSend;
    }

    this.isActive = false;
  }

  /**
   * Intercept fetch API
   */
  private interceptFetch(): void {
    if (typeof fetch === "undefined") return;

    this.originalFetch = fetch;

    globalThis.fetch = async (...args: Parameters<typeof fetch>) => {
      const startTime = Date.now();
      const url =
        typeof args[0] === "string"
          ? args[0]
          : args[0] instanceof URL
            ? args[0].href
            : args[0].url;
      const method = args[1]?.method || "GET";

      try {
        const response = await this.originalFetch!(...args);
        const duration = Date.now() - startTime;

        this.addRequest({
          url,
          method,
          status: response.status,
          statusText: response.statusText,
          duration,
          timestamp: startTime,
          requestHeaders: this.extractHeaders(args[1]?.headers),
          responseHeaders: this.extractHeaders(response.headers),
        });

        return response;
      } catch (error) {
        const duration = Date.now() - startTime;

        this.addRequest({
          url,
          method,
          duration,
          timestamp: startTime,
          requestHeaders: this.extractHeaders(args[1]?.headers),
        });

        throw error;
      }
    };
  }

  /**
   * Intercept XMLHttpRequest
   */
  private interceptXHR(): void {
    if (typeof XMLHttpRequest === "undefined") return;

    this.originalXHROpen = XMLHttpRequest.prototype.open;
    this.originalXHRSend = XMLHttpRequest.prototype.send;

    const collector = this;

    XMLHttpRequest.prototype.open = function (
      this: XMLHttpRequest,
      method: string,
      url: string | URL,
      async?: boolean,
      username?: string | null,
      password?: string | null
    ) {
      (this as any).__catchfn_method = method;
      (this as any).__catchfn_url = String(url);
      (this as any).__catchfn_startTime = Date.now();

      return collector.originalXHROpen!.call(
        this,
        method,
        url,
        async ?? true,
        username,
        password
      );
    };

    XMLHttpRequest.prototype.send = function (...args: any[]) {
      this.addEventListener("loadend", function () {
        const duration = Date.now() - (this as any).__catchfn_startTime;

        collector.addRequest({
          url: (this as any).__catchfn_url,
          method: (this as any).__catchfn_method,
          status: this.status,
          statusText: this.statusText,
          duration,
          timestamp: (this as any).__catchfn_startTime,
        });
      });

      return collector.originalXHRSend!.call(this, ...args);
    };
  }

  /**
   * Extract and sanitize headers
   */
  private extractHeaders(
    headers?: HeadersInit | Headers
  ): Record<string, string> | undefined {
    if (!headers) return undefined;

    const result: Record<string, string> = {};

    if (headers instanceof Headers) {
      headers.forEach((value, key) => {
        if (!this.sensitiveHeaders.has(key.toLowerCase())) {
          result[key] = value;
        } else {
          result[key] = "[REDACTED]";
        }
      });
    } else if (Array.isArray(headers)) {
      headers.forEach(([key, value]) => {
        if (!this.sensitiveHeaders.has(key.toLowerCase())) {
          result[key] = value;
        } else {
          result[key] = "[REDACTED]";
        }
      });
    } else {
      Object.entries(headers).forEach(([key, value]) => {
        if (!this.sensitiveHeaders.has(key.toLowerCase())) {
          result[key] = String(value);
        } else {
          result[key] = "[REDACTED]";
        }
      });
    }

    return result;
  }

  /**
   * Add a network request
   */
  private addRequest(request: NetworkRequest): void {
    this.requests.push(request);

    // Maintain size limit
    if (this.requests.length > this.maxSize) {
      this.requests.shift();
    }
  }

  /**
   * Collect all network requests
   */
  collect(): NetworkRequest[] {
    return [...this.requests];
  }

  /**
   * Clear all network requests
   */
  clear(): void {
    this.requests = [];
  }

  /**
   * Get the current number of requests
   */
  size(): number {
    return this.requests.length;
  }
}
/**
 * Console log collector - captures console output
 */

import type { ConsoleLogEntry, ContextCollector } from "../core/types.js";

type ConsoleMethod = "log" | "info" | "warn" | "error" | "debug";

export class ConsoleCollector implements ContextCollector<ConsoleLogEntry[]> {
  private logs: ConsoleLogEntry[] = [];
  private maxSize: number;
  private originalMethods: Map<ConsoleMethod, (...args: any[]) => void> =
    new Map();
  private isActive = false;

  constructor(maxSize: number = 100) {
    this.maxSize = maxSize;
  }

  /**
   * Start intercepting console methods
   */
  start(): void {
    if (this.isActive) return;

    const methods: ConsoleMethod[] = ["log", "info", "warn", "error", "debug"];

    methods.forEach((method) => {
      // Store original method
      this.originalMethods.set(method, console[method].bind(console));

      // Replace with interceptor
      console[method] = (...args: any[]) => {
        // Call original
        this.originalMethods.get(method)?.(...args);

        // Capture
        this.capture(method, args);
      };
    });

    this.isActive = true;
  }

  /**
   * Stop intercepting console methods
   */
  stop(): void {
    if (!this.isActive) return;

    this.originalMethods.forEach((original, method) => {
      console[method] = original;
    });

    this.originalMethods.clear();
    this.isActive = false;
  }

  /**
   * Capture a console log entry
   */
  private capture(level: ConsoleMethod, args: any[]): void {
    const entry: ConsoleLogEntry = {
      level,
      args: this.serializeArgs(args),
      timestamp: Date.now(),
    };

    this.logs.push(entry);

    // Maintain size limit
    if (this.logs.length > this.maxSize) {
      this.logs.shift();
    }
  }

  /**
   * Serialize console arguments
   */
  private serializeArgs(args: any[]): any[] {
    return args.map((arg) => {
      if (arg === null) return null;
      if (arg === undefined) return undefined;
      if (typeof arg === "string") return arg;
      if (typeof arg === "number") return arg;
      if (typeof arg === "boolean") return arg;
      if (arg instanceof Error) {
        return {
          name: arg.name,
          message: arg.message,
          stack: arg.stack,
        };
      }
      // For objects, try to stringify
      try {
        return JSON.parse(JSON.stringify(arg));
      } catch {
        return String(arg);
      }
    });
  }

  /**
   * Collect all console logs
   */
  collect(): ConsoleLogEntry[] {
    return [...this.logs];
  }

  /**
   * Clear all console logs
   */
  clear(): void {
    this.logs = [];
  }

  /**
   * Get the current number of logs
   */
  size(): number {
    return this.logs.length;
  }
}
/**
 * Error and data serialization utilities
 */

/**
 * Serialize an Error object
 */
export function serializeError(error: Error): Record<string, any> {
  return {
    name: error.name,
    message: error.message,
    stack: error.stack,
    ...Object.getOwnPropertyNames(error).reduce(
      (acc, key) => {
        if (key !== "name" && key !== "message" && key !== "stack") {
          acc[key] = (error as any)[key];
        }
        return acc;
      },
      {} as Record<string, any>
    ),
  };
}

/**
 * Safely serialize any value, handling circular references
 */
export function safeSerialize(value: any, maxDepth: number = 10): any {
  const seen = new WeakSet();

  function serialize(val: any, depth: number): any {
    if (depth > maxDepth) {
      return "[Max Depth Reached]";
    }

    if (val === null) return null;
    if (val === undefined) return undefined;
    if (typeof val === "string") return val;
    if (typeof val === "number") return val;
    if (typeof val === "boolean") return val;
    if (typeof val === "function") return "[Function]";
    if (typeof val === "symbol") return val.toString();

    if (val instanceof Error) {
      return serializeError(val);
    }

    if (val instanceof Date) {
      return val.toISOString();
    }

    if (val instanceof RegExp) {
      return val.toString();
    }

    if (typeof val === "object") {
      if (seen.has(val)) {
        return "[Circular Reference]";
      }

      seen.add(val);

      if (Array.isArray(val)) {
        return val.map((item) => serialize(item, depth + 1));
      }

      const result: Record<string, any> = {};
      for (const key in val) {
        if (Object.prototype.hasOwnProperty.call(val, key)) {
          result[key] = serialize(val[key], depth + 1);
        }
      }
      return result;
    }

    return String(val);
  }

  return serialize(value, 0);
}

/**
 * Estimate the size of a serialized object in bytes
 */
export function estimateSize(obj: any): number {
  try {
    const str = JSON.stringify(safeSerialize(obj));
    return new Blob([str]).size;
  } catch {
    return 0;
  }
}

/**
 * Truncate a string to a maximum length
 */
export function truncateString(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str;
  return str.substring(0, maxLength - 3) + "...";
}

/**
 * Trim an array to a maximum size
 */
export function trimArray<T>(arr: T[], maxSize: number): T[] {
  if (arr.length <= maxSize) return arr;
  return arr.slice(-maxSize);
}

