import type { ConsoleLogEntry, ContextCollector } from "../core/types.js";

type ConsoleMethod = "log" | "info" | "warn" | "error" | "debug";

export class ConsoleCollector implements ContextCollector<ConsoleLogEntry[]> {
  private logs: ConsoleLogEntry[] = [];
  private maxSize: number;
  private originalMethods: Map<ConsoleMethod, (...args: any[]) => void> =
    new Map();
  private isActive = false;

  constructor(maxSize: number = 100) {
    this.maxSize = maxSize;
  }

  /**
   * Start intercepting console methods
   */
  start(): void {
    if (this.isActive) return;

    const methods: ConsoleMethod[] = ["log", "info", "warn", "error", "debug"];

    methods.forEach((method) => {
      // Store original method
      this.originalMethods.set(method, console[method].bind(console));

      // Replace with interceptor
      console[method] = (...args: any[]) => {
        // Call original
        this.originalMethods.get(method)?.(...args);

        // Capture
        this.capture(method, args);
      };
    });

    this.isActive = true;
  }

  /**
   * Stop intercepting console methods
   */
  stop(): void {
    if (!this.isActive) return;

    this.originalMethods.forEach((original, method) => {
      console[method] = original;
    });

    this.originalMethods.clear();
    this.isActive = false;
  }

  /**
   * Capture a console log entry
   */
  private capture(level: ConsoleMethod, args: any[]): void {
    const entry: ConsoleLogEntry = {
      level,
      args: this.serializeArgs(args),
      timestamp: Date.now(),
    };

    this.logs.push(entry);

    // Maintain size limit
    if (this.logs.length > this.maxSize) {
      this.logs.shift();
    }
  }

  /**
   * Serialize console arguments
   */
  private serializeArgs(args: any[]): any[] {
    return args.map((arg) => {
      if (arg === null) return null;
      if (arg === undefined) return undefined;
      if (typeof arg === "string") return arg;
      if (typeof arg === "number") return arg;
      if (typeof arg === "boolean") return arg;
      if (arg instanceof Error) {
        return {
          name: arg.name,
          message: arg.message,
          stack: arg.stack,
        };
      }
      // For objects, try to stringify
      try {
        return JSON.parse(JSON.stringify(arg));
      } catch {
        return String(arg);
      }
    });
  }

  /**
   * Collect all console logs
   */
  collect(): ConsoleLogEntry[] {
    return [...this.logs];
  }

  /**
   * Clear all console logs
   */
  clear(): void {
    this.logs = [];
  }

  /**
   * Get the current number of logs
   */
  size(): number {
    return this.logs.length;
  }
}
/**
 * Error and data serialization utilities
 */

/**
 * Serialize an Error object
 */
export function serializeError(error: Error): Record<string, any> {
  return {
    name: error.name,
    message: error.message,
    stack: error.stack,
    ...Object.getOwnPropertyNames(error).reduce(
      (acc, key) => {
        if (key !== "name" && key !== "message" && key !== "stack") {
          acc[key] = (error as any)[key];
        }
        return acc;
      },
      {} as Record<string, any>
    ),
  };
}

/**
 * Safely serialize any value, handling circular references
 */
export function safeSerialize(value: any, maxDepth: number = 10): any {
  const seen = new WeakSet();

  function serialize(val: any, depth: number): any {
    if (depth > maxDepth) {
      return "[Max Depth Reached]";
    }

    if (val === null) return null;
    if (val === undefined) return undefined;
    if (typeof val === "string") return val;
    if (typeof val === "number") return val;
    if (typeof val === "boolean") return val;
    if (typeof val === "function") return "[Function]";
    if (typeof val === "symbol") return val.toString();

    if (val instanceof Error) {
      return serializeError(val);
    }

    if (val instanceof Date) {
      return val.toISOString();
    }

    if (val instanceof RegExp) {
      return val.toString();
    }

    if (typeof val === "object") {
      if (seen.has(val)) {
        return "[Circular Reference]";
      }

      seen.add(val);

      if (Array.isArray(val)) {
        return val.map((item) => serialize(item, depth + 1));
      }

      const result: Record<string, any> = {};
      for (const key in val) {
        if (Object.prototype.hasOwnProperty.call(val, key)) {
          result[key] = serialize(val[key], depth + 1);
        }
      }
      return result;
    }

    return String(val);
  }

  return serialize(value, 0);
}

/**
 * Estimate the size of a serialized object in bytes
 */
export function estimateSize(obj: any): number {
  try {
    const str = JSON.stringify(safeSerialize(obj));
    return new Blob([str]).size;
  } catch {
    return 0;
  }
}

/**
 * Truncate a string to a maximum length
 */
export function truncateString(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str;
  return str.substring(0, maxLength - 3) + "...";
}

/**
 * Trim an array to a maximum size
 */
export function trimArray<T>(arr: T[], maxSize: number): T[] {
  if (arr.length <= maxSize) return arr;
  return arr.slice(-maxSize);
}
