    restore = () => { for (const cleanup of cleanups) cleanup(); };
  }
  const current = listeners;
  current.add(listener);
  return () => {
    current.delete(listener);
    if (current === listeners && current.size === 0) { restore?.(); restore = undefined; }
  };
