"""Validated durable bug reports using the shared adapter contract."""
from __future__ import annotations

import base64
import json
import math
import re
import time
from typing import Any, Callable, Dict, List, Optional
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

from superfunctions.db import (
    Adapter, CreateParams, DeleteManyParams, FindManyParams, FindOneParams,
    Operator, OrderBy, WhereClause,
)
from .schema import validate_table_name
from .types import BugReportEvent


class CatchFnValidationError(ValueError):
    pass


class CatchFnConflictError(ValueError):
    pass


_SENSITIVE = re.compile(r"password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key|auth|credit[_-]?card|card[_-]?number|cvv|ssn", re.I)
_CARD = re.compile(r"\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b")


def _redact(value: Any, key: str = "") -> Any:
    if isinstance(value, dict):
        return {name: "[REDACTED]" if _SENSITIVE.search(name) else _redact(item, name) for name, item in value.items()}
    if isinstance(value, list):
        return [_redact(item, key) for item in value]
    if isinstance(value, str):
        if re.search(r"url|href", key, re.I):
