  catcher: CatchFn;
  onReporterError?: (error: unknown) => void;
}
/** React delegates capture and lifecycle ownership to the same vanilla SDK. */
export function CatchFnReporterButton({catcher, onReporterError, children = "Report a bug", ...props}: CatchFnReporterButtonProps) {
  return createElement("button", {...props, type:props.type ?? "button", onClick:(event) => {
